I made DL inferences under multiple threads in libtorch as following:
#include <torch/torch.h>
#include <torch/script.h>

#include <nvToolsExt.h>
#include <unistd.h>
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <semaphore.h>
#include <pthread.h>
#include <atomic>

torch::Device device(torch::kCUDA);
int thread_num = 2;
sem_t barrier;
std::atomic<int> count(thread_num);

void solo_run(torch::jit::script::Module& model, std::vector<torch::jit::IValue>& imgs)
{
	model.to(device);
	for (int i = 0; i < 100; ++i)
		model.forward(imgs);

	torch::cuda::synchronize();
}

void parallel(torch::jit::script::Module model)
{
	model.to(device);
	torch::Tensor img = torch::rand({4, 3, 224, 224}).to(device);
	std::vector<torch::jit::IValue> imgs;
	imgs.push_back(img);

	count--;
	if (count == 0) {
		for (int i = 0; i < thread_num; ++i) {
			sem_post(&barrier);
		}
	}
	sem_wait(&barrier);

	nvtxRangePushA("PARALLEL");
	for (int i = 0; i < 100; ++i)
		model.forward(imgs);

	nvtxRangePop();
}

int main(int arc, char** argv) {
	sem_init(&barrier, 0, 0);

	c10::InferenceMode guard(true);
	torch::Tensor img = torch::rand({4, 3, 224, 224}).to(device);
	std::vector<torch::jit::IValue> inputs;
	inputs.push_back(img);
	std::string model_path = argv[1];

	torch::jit::script::Module model = torch::jit::load(model_path);
	// auto model = torch::jit::load(model_path);

	std::vector<torch::jit::script::Module> models;
	for (int i = 0; i < thread_num; ++i) {
		models.push_back(torch::jit::load(model_path));
	}
	if(torch::cuda::is_available()) {
		std::cout << "CUDA now is available ! Inference on GPU." << std::endl;
	}

	// warm up
	solo_run(model, inputs);

	nvtxRangePushA("Single");
	solo_run(model, inputs);
	nvtxRangePop();

	std::cout << "Start parallel inference !!!" << std::endl;
	std::vector<std::thread> threads;
	threads.reserve(thread_num);

	for (int j = 0; j < thread_num; ++j) {
		threads.emplace_back(parallel, models[j]);
	}

	for (int k = 0; k < thread_num; ++k) {
		threads[k].join();
	}


	torch::cuda::synchronize();
	std::cout << "Finished successfully !!!" << std::endl;

	sem_destroy(&barrier);

}

